} Layer;

static void die(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    exit(1);
}

static Layer *load_model(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) die("cannot open weights.json");
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (sz <= 0) die("weights.json is empty");
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) die("out of memory");
    if (fread(buf, 1, (size_t)sz, f) != (size_t)sz) die("failed to read weights.json");
    buf[sz] = 0;
    fclose(f);

    cJSON *root = cJSON_Parse(buf);
    free(buf);
    if (!root) die("invalid JSON in weights.json");

    int input_dim = 784, hidden_dim = 16, num_classes = 10;
    cJSON *j;
    if ((j = cJSON_GetObjectItem(root, "input_dim")) && j->type == cJSON_Number)
        input_dim = j->valueint;
    if ((j = cJSON_GetObjectItem(root, "hidden_dim")) && j->type == cJSON_Number)
        hidden_dim = j->valueint;
    if ((j = cJSON_GetObjectItem(root, "num_classes")) && j->type == cJSON_Number)
        num_classes = j->valueint;

    /* Determine dims from the layer arrays when metadata is missing. */
    cJSON *layers = cJSON_GetObjectItem(root, "layers");
    if (!layers || cJSON_GetArraySize(layers) != 3) die("weights.json must have 3 layers");

    /* Infer dims from the weight matrices (rows x cols) to stay robust. */
    int dim[4] = {input_dim, hidden_dim, hidden_dim, num_classes};
    for (int li = 0; li < 3; li++) {
        cJSON *L = cJSON_GetArrayItem(layers, li);
        cJSON *w = cJSON_GetObjectItem(L, "weight");
        if (!w || !cJSON_IsArray(w)) die("layer missing weight array");
        int rows = cJSON_GetArraySize(w);
        cJSON *row0 = w->child;
        int cols = row0 ? cJSON_GetArraySize(row0) : 0;
        dim[li + 1] = rows;
        if (li == 0) dim[0] = cols;
    }

    Layer *model = (Layer *)calloc(3, sizeof(Layer));
    if (!model) die("out of memory");

    for (int li = 0; li < 3; li++) {
        cJSON *L = cJSON_GetArrayItem(layers, li);
        cJSON *w = cJSON_GetObjectItem(L, "weight");
        cJSON *b = cJSON_GetObjectItem(L, "bias");
        if (!w || !cJSON_IsArray(w)) die("layer missing weight");
        if (!b || !cJSON_IsArray(b)) die("layer missing bias");

        int in_dim = dim[li], out_dim = dim[li + 1];
        cJSON *row0 = w->child;
        int actual_in = row0 ? cJSON_GetArraySize(row0) : in_dim;

        model[li].in_dim = actual_in;
        model[li].out_dim = out_dim;
        model[li].relu = (li < 2);

        model[li].weight = (float *)malloc(sizeof(float) * (size_t)out_dim * actual_in);
        model[li].bias = (float *)malloc(sizeof(float) * (size_t)out_dim);
        if (!model[li].weight || !model[li].bias) die("out of memory");

        int r = 0;
        for (cJSON *row = w->child; row; row = row->next, r++) {
            if (r >= out_dim) die("too many weight rows");
            int c = 0;
            for (cJSON *e = row->child; e; e = e->next, c++) {
                if (c >= actual_in) die("too many weight cols");
                model[li].weight[(size_t)r * actual_in + c] = (float)e->valuedouble;
            }
            if (c != actual_in) die("weight row length mismatch");
        }
        if (r != out_dim) die("too few weight rows");

        int bi = 0;
        for (cJSON *e = b->child; e; e = e->next, bi++) {
            if (bi >= out_dim) die("too many bias entries");
            model[li].bias[bi] = (float)e->valuedouble;
        }
        if (bi != out_dim) die("bias length mismatch");
    }

    cJSON_Delete(root);
    return model;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }

    Layer *model = load_model(argv[1]);

    unsigned w = 0, h = 0;
    float *x = NULL;
    if (load_png_gray(argv[2], &w, &h, &x) != 0) {
        fprintf(stderr, "cannot decode %s\n", argv[2]);
        return 1;
    }
    if (w * h != (unsigned)model[0].in_dim) {
        fprintf(stderr, "image is %ux%u, expected %d pixels\n", w, h, model[0].in_dim);
        free(x);
        return 1;
    }

    /* forward pass (double-precision accumulation) */
    int max_out = 0;
    for (int li = 0; li < 3; li++)
        if (model[li].out_dim > max_out) max_out = model[li].out_dim;

    float *buf0 = (float *)malloc(sizeof(float) * (size_t)max_out);
    float *buf1 = (float *)malloc(sizeof(float) * (size_t)max_out);
    if (!buf0 || !buf1) die("out of memory");

    float *cur = x;
    float *next = buf0;
    int cur_len = model[0].in_dim;
    int use_buf = 0;

    for (int li = 0; li < 3; li++) {
        Layer *L = &model[li];
        for (int o = 0; o < L->out_dim; o++) {
            double s = (double)L->bias[o];
            const float *wr = L->weight + (size_t)o * L->in_dim;
            for (int j = 0; j < L->in_dim; j++)
                s += (double)wr[j] * cur[j];
            next[o] = (L->relu && s < 0.0) ? 0.0f : (float)s;
        }
        cur = next;
        next = use_buf ? buf0 : buf1;
        use_buf ^= 1;
        cur_len = L->out_dim;
    }

    /* argmax */
    int best = 0;
    for (int i = 1; i < cur_len; i++)
        if (cur[i] > cur[best]) best = i;

    printf("%d\n", best);
    free(buf0);
    free(buf1);
    return 0;
}
